UPDATE reviewed_module SET reviewed_at='2026-09-18', content_json='{"reviewed_at":"2026-09-18","refresh":"Manual snapshot; latest chart period ends 30 June 2026","sources":{"trend":{"title":"Small boat arrivals: year ending June 2026","url":"https://www.gov.uk/government/statistics/immigration-system-statistics-year-ending-june-2026/how-many-people-come-to-the-uk-via-illegal-entry-routes","date":"2026-08-27","locator":"Sections 2.1–2.2; IER_02a"},"annual":{"title":"Small boat arrivals: calendar year 2025","url":"https://www.gov.uk/government/statistics/immigration-system-statistics-year-ending-december-2025/how-many-people-come-to-the-uk-via-illegal-entry-routes","date":"2026-02-26","locator":"Section 2.1"},"nca":{"title":"National Strategic Assessment 2026: border","publisher":"National Crime Agency","url":"https://www.nationalcrimeagency.gov.uk/nsa-domains-2026/nsa-soc-at-the-border-2026","date":null,"locator":"The Sea Border — Small Boats"},"daily":{"title":"Daily and weekly Channel activity","url":"https://www.gov.uk/government/publications/migrants-detected-crossing-the-english-channel-in-small-boats","date":"2026-09-17","locator":"Documents and Details"},"processing":{"title":"Initial processing: Home Office factsheet","url":"https://www.gov.uk/government/publications/manston-arrivals-and-processing-centre/manston-factsheet","date":"2026-02-25","locator":"Initial processing and immediate healthcare"},"screening":{"title":"Claim asylum: screening","url":"https://www.gov.uk/claim-asylum/screening","date":null,"locator":"Attend an asylum screening"},"routing":{"title":"Claim asylum: after screening","url":"https://www.gov.uk/claim-asylum/after-your-screening","date":null,"locator":"Consideration in the UK; detention; caseworkers"},"support":{"title":"Asylum support","url":"https://www.gov.uk/asylum-support","date":null,"locator":"Overview and eligibility"},"interview":{"title":"Claim asylum: interview","url":"https://www.gov.uk/claim-asylum/asylum-interview","date":null,"locator":"Evidence and what happens in the interview"},"decision":{"title":"Claim asylum: decision and next steps","url":"https://www.gov.uk/claim-asylum/decision","date":null,"locator":"Successful claim; no reason to stay"},"france":{"title":"UK–France agreement: transfers and returns","url":"https://www.gov.uk/government/publications/the-border-security-commanders-annual-report-data/transfers-into-and-returns-from-the-united-kingdom-under-the-uk-france-agreement-on-the-prevention-of-dangerous-journeys-between-6-august-2025-and-30","date":null,"locator":"6 August 2025–30 June 2026"},"history":{"title":"Small boat history: June 2026 tables","publisher":"Home Office","url":"https://assets.publishing.service.gov.uk/media/6a8c11c3a8f84a582b84281a/illegal-entry-routes-to-the-uk-summary-jun-2026-tables.ods","date":"2026-08-27","locator":"IER_01, small boat arrivals; notes 2–5 and 9"}},"comparisons":{"history":{"title":"Longer view · complete calendar years 2018–2025","unit":"people","rows":[["2018",299],["2019",1843],["2020",8466],["2021",28526],["2022",45774],["2023",29437],["2024",36816],["2025",41472]],"source":"history","notes":"Complete calendar years only. Change shown is 2025 versus 2024. June 2026 release vintage: figures can be revised; enhanced processing applies from January 2025. Partial 2026 is excluded.","published":"27 August 2026"},"rolling":{"title":"Latest quarterly release · years ending June","unit":"people","rows":[["July 2023–June 2024",31493],["July 2024–June 2025",43309],["July 2025–June 2026",33374]],"source":"trend","notes":"Complete 12-month periods with the same seasonal coverage. This is not the January–June 2026 total.","published":"27 August 2026"},"calendar":{"title":"Complete calendar years · 2024 and 2025","unit":"people","rows":[["January–December 2024",36816],["January–December 2025",41472]],"source":"nca","notes":"Two complete calendar years. This increase and the later rolling-year decrease describe different periods.","published":"2026 assessment; exact date not recorded"}},"stages":[{"title":"Arrival & initial processing","body":"People brought to the UK enter initial processing. Officials collect and verify identity and other details, with immediate healthcare needs addressed. Initial processing is distinct from the later decision on an asylum claim.","sources":["processing"]},{"title":"Register an asylum claim","body":"A person seeking protection tells an immigration officer. Screening records identity, photographs and fingerprints, the reason for claiming, and relevant medical information. An interpreter can be requested. Registration does not itself grant refugee status.","sources":["screening"]},{"title":"Decide where the claim is considered","body":"The Home Office considers whether to examine the claim in the UK. A safe-third-country connection may trigger an inadmissibility process. Transfer depends on applicable arrangements and the individual case; arrival from France does not mean every person is automatically returned.","sources":["routing","france"]},{"title":"While the case is pending","body":"Eligible people who cannot support themselves may receive accommodation and financial support. Reporting requirements can apply. Some people may be detained; others are not. Children and people with particular vulnerabilities require different consideration.","sources":["support","routing"]},{"title":"Evidence & asylum interview","body":"Where the claim is examined, the applicant explains why they fear return and supplies supporting evidence. A substantive interview explores the protection claim in more detail than screening. Interpretation is available where needed.","sources":["interview"]},{"title":"Decision on protection","body":"A successful claim can lead to refugee status or humanitarian protection; other permission is possible. The length and conditions of permission depend on the applicable rules and claim date. Recognition is not automatic citizenship or permanent settlement.","sources":["decision"]},{"title":"Appeal or departure","body":"A refusal may carry a right of appeal. If there is no remaining permission or legal basis to stay after the relevant process, departure may be voluntary or enforced. A refusal, an appeal outcome and an actual return are separate events.","sources":["decision"]}],"process_reviewed_at":"2026-09-17"}' WHERE id='small-boats';
INSERT INTO reviewed_module VALUES ('waiting-backlogs','2026-09-18','{"reviewed_at":"2026-09-18","refresh":"Manual reviewed snapshot, not a live feed","sources":{"asylum":{"title":"People in the UK asylum system, June 2026","publisher":"Home Office","date":"2026-08-27","url":"https://www.gov.uk/government/statistics/immigration-system-statistics-year-ending-june-2026/how-many-people-are-in-the-uk-asylum-system","locator":"Sections 1–2; Asy_D03 and ASY_03"},"tribunal":{"title":"Tribunal statistics, April–June 2026","publisher":"Ministry of Justice","date":"2026-09-10","url":"https://www.gov.uk/government/statistics/tribunals-statistics-quarterly-april-to-june-2026/tribunal-statistics-quarterly-april-to-june-2026","locator":"Section 5, Immigration and Asylum; FIA_4 and timeliness"},"crossings":{"title":"Detected entry routes: measurement limits","publisher":"Home Office","date":"2026-08-27","url":"https://www.gov.uk/government/statistics/immigration-system-statistics-year-ending-june-2026/how-many-people-come-to-the-uk-via-illegal-entry-routes","locator":"Sections 1 and 3"}},"measures":[{"id":"initial-people","title":"Awaiting an initial decision","value":40168,"display":"40,168","unit":"people","period":"30 June 2026","population":"Main applicants and dependants awaiting an initial asylum decision","kind":"Snapshot","note":"Down 56% from June 2025 (publisher-rounded).","source":"asylum","exclusions":"Excludes later appeal and removal stages. Not the number of new claims this quarter."},{"id":"initial-cases","title":"The same initial queue, counted as cases","value":32401,"display":"32,401","unit":"cases","period":"30 June 2026","population":"Main applicants awaiting an initial asylum decision","kind":"Snapshot","note":"The same queue as 40,168 people, counted differently.","source":"asylum","exclusions":"Dependants are not separate cases. Do not add this count to the people count."},{"id":"appeals-open","title":"Open immigration and asylum appeals","value":156000,"display":"156,000","unit":"cases · rounded","period":"30 June 2026","population":"All First-tier Tribunal Immigration and Asylum Chamber categories","kind":"Snapshot","note":"Up 48% from June 2025 (publisher-rounded). Includes non-asylum appeals.","source":"tribunal","exclusions":"Not an asylum-only total. Excludes Upper Tribunal proceedings. Must not be added to the initial-decision people count."},{"id":"appeals-time","title":"Asylum/protection appeal clearance time","value":72,"display":"72","unit":"weeks · mean","period":"Appeals cleared April–June 2026","population":"Asylum/Protection appeals cleared by the First-tier Tribunal","kind":"Duration","note":"An average for completed appeals, not a promised wait for a new appeal.","source":"tribunal","exclusions":"Not the age of currently open cases, not a median, and not the entire time from arrival or asylum claim."}],"initialHistory":[["December 2010",7240],["December 2018",35855],["June 2023",175457],["June 2026",40168]],"unknowns":{"undetected":{"value":null,"status":"no_official_estimate","source":"crossings"},"overall_casework_after_june_2024":{"value":null,"status":"publication_gap","source":"asylum"},"pending_wait_age":{"value":null,"status":"not_imported"}}}');
